<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Under the Wave off Kanagawa — Low-Poly 3D Wallpaper</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@600;800&display=swap" rel="stylesheet" />
  <style>
    :root {
      --sky-ochre: #f6e6bf;
      --sky-cream: #faf2dc;
      --horizon-slate: #747572;
      --prussian-deep: #152d4c;
      --prussian-mid: #234975;
      --aqua-stripe: #538aa6;
      --seafoam-pale: #9cc0ba;
      --foam-ivory: #f7f5e4;
      --boat-cedar: #e7b590;
      --cartouche-bg: #e5ded0;
      --ink-blue: #182f4e;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html, body {
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: linear-gradient(
        180deg,
        #f4e2b8 0%,
        #f8edd0 36%,
        #dcd6c4 58%,
        #787975 74%,
        #1c385c 76%,
        #152d4c 100%
      );
      font-family: "Shippori Mincho", "Yu Mincho", "Hiragino Mincho ProN", serif;
      user-select: none;
    }

    #scene-canvas {
      position: fixed;
      inset: 0;
      width: 100vw;
      height: 100vh;
      display: block;
    }

    /* Woodblock cartouche & signature homage at top-left */
    .ukiyo-header {
      position: fixed;
      top: 5.5vh;
      left: 3.4vw;
      display: flex;
      flex-direction: row-reverse;
      align-items: flex-start;
      gap: 12px;
      pointer-events: none;
      z-index: 10;
      opacity: 0.92;
    }

    .cartouche {
      background: var(--cartouche-bg);
      border: 2px solid var(--ink-blue);
      outline: 1px solid var(--ink-blue);
      outline-offset: 2px;
      padding: 8px 6px;
      writing-mode: vertical-rl;
      text-orientation: upright;
      color: var(--ink-blue);
      box-shadow: 0 2px 8px rgba(21, 45, 76, 0.12);
    }

    .cartouche-series {
      font-size: clamp(12px, 1.35vh, 16px);
      font-weight: 800;
      letter-spacing: 0.12em;
      line-height: 1.25;
    }

    .cartouche-sub {
      font-size: clamp(10px, 1.1vh, 13px);
      font-weight: 600;
      letter-spacing: 0.08em;
      margin-right: 3px;
      padding-top: 28px;
    }

    .signature {
      margin-top: 72px;
      writing-mode: vertical-rl;
      text-orientation: upright;
      color: var(--ink-blue);
      font-size: clamp(10px, 1.15vh, 13px);
      font-weight: 600;
      letter-spacing: 0.14em;
      opacity: 0.84;
      text-shadow: 0 0 2px rgba(250, 242, 220, 0.8);
    }

    /* Subtle paper grain vignette */
    .washi-overlay {
      position: fixed;
      inset: 0;
      pointer-events: none;
      z-index: 8;
      background:
        radial-gradient(ellipse at 54% 38%, transparent 58%, rgba(196, 173, 130, 0.22) 100%);
      mix-blend-mode: multiply;
    }
  </style>
</head>
